    ) as t(match_id, match_date, formation, field_players, bench_players, placed_names)
  loop
    select d.present_names into v_present
    from public.historical_match_details d
    join public.historical_match_scores s on s.id = d.match_id
    where d.match_id = v_row.match_id
      and s.match_date = v_row.match_date
      and coalesce(jsonb_array_length(d.field_players), 0) = 0
    for update of d;

    if not found then
      continue;
    end if;

    select coalesce(array_agg(n order by n), '{}') into v_expected
    from jsonb_array_elements_text(v_present) as p(n)
    where n <> 'Philippe Couzin';

    select coalesce(array_agg(n order by n), '{}') into v_placed
    from jsonb_array_elements_text(v_row.placed_names) as p(n);

    if v_expected is distinct from v_placed then
      raise exception 'Composition reconstituée incohérente pour le match du % : présents % / placés %',
        v_row.match_date, v_expected, v_placed;
    end if;

    update public.historical_match_details
    set formation = v_row.formation,
        field_players = v_row.field_players,
        bench_players = v_row.bench_players
    where match_id = v_row.match_id;
  end loop;
end
